import csv
import hashlib
import json
import sqlite3
import sys
from datetime import datetime
from pathlib import Path

ROOT = Path('/workspace')
EXPECTED_HASHES = {
    'incidents.csv': '4b0e407424b0c122c95e69853ed259a24871f6feb50562b6bd92a726c9596870',
    'maintenance.json': 'ad40e946951d7b1b3d4c150cc9b94eedd01b29f3fd4d11ab99ab8fbb03f0a83f',
}

def fail(message):
    raise AssertionError(message)

def main():
    # Inputs are solver-writable state, so authenticate them against private constants first.
    for name, expected in EXPECTED_HASHES.items():
        path = ROOT/'input'/name
        if not path.is_file():
            fail(f'missing source {name}')
        actual = hashlib.sha256(path.read_bytes()).hexdigest()
        if actual != expected:
            fail(f'source {name} was modified')

    with (ROOT/'input/incidents.csv').open(newline='', encoding='utf-8') as f:
        source = list(csv.DictReader(f))
    windows = json.loads((ROOT/'input/maintenance.json').read_text(encoding='utf-8'))['windows']
    latest = {}
    for row in source:
        revision = int(row['revision'])
        if row['incident_id'] not in latest or revision > int(latest[row['incident_id']]['revision']):
            latest[row['incident_id']] = row

    parse = lambda s: datetime.fromisoformat(s.replace('Z', '+00:00'))
    expected_incidents = []
    expected_tags = []
    for iid, row in latest.items():
        planned = any(w['service'] == row['service'] and w['start'] <= row['started_at'] and row['ended_at'] <= w['end'] for w in windows)
        duration = int((parse(row['ended_at']) - parse(row['started_at'])).total_seconds() // 60)
        expected_incidents.append((iid, row['service'], int(row['severity']), row['started_at'], row['ended_at'], duration, int(row['revision']), 'planned' if planned else 'unplanned'))
        expected_tags.extend((iid, tag) for tag in sorted({v.strip().lower() for v in row['tags'].split('|') if v.strip()}))
    expected_incidents.sort()
    expected_tags.sort()

    dbpath = ROOT/'audit.sqlite'
    if not dbpath.is_file():
        fail('audit.sqlite is missing')
    con = sqlite3.connect(f'file:{dbpath}?mode=ro', uri=True)
    objects = con.execute("SELECT type,name FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name").fetchall()
    if objects != [('table','incident_tags'), ('table','incidents'), ('view','service_summary')]:
        fail(f'unexpected database objects: {objects}')

    inc_schema = con.execute('PRAGMA table_info(incidents)').fetchall()
    tag_schema = con.execute('PRAGMA table_info(incident_tags)').fetchall()
    inc_signature = [(r[1], r[2].upper(), r[3], r[5]) for r in inc_schema]
    tag_signature = [(r[1], r[2].upper(), r[3], r[5]) for r in tag_schema]
    if inc_signature != [('incident_id','TEXT',0,1),('service','TEXT',1,0),('severity','INTEGER',1,0),('started_at','TEXT',1,0),('ended_at','TEXT',1,0),('duration_min','INTEGER',1,0),('revision','INTEGER',1,0),('disposition','TEXT',1,0)]:
        fail(f'incidents schema mismatch: {inc_signature}')
    if tag_signature != [('incident_id','TEXT',1,1),('tag','TEXT',1,2)]:
        fail(f'incident_tags schema mismatch: {tag_signature}')
    foreign_keys = con.execute('PRAGMA foreign_key_list(incident_tags)').fetchall()
    if len(foreign_keys) != 1 or foreign_keys[0][2:5] != ('incidents', 'incident_id', 'incident_id'):
        fail(f'incident_tags foreign key mismatch: {foreign_keys}')
    incident_sql = con.execute("SELECT lower(sql) FROM sqlite_master WHERE type='table' AND name='incidents'").fetchone()[0]
    if 'check(severity between 1 and 4)' not in incident_sql.replace('  ', ' ') or "check(disposition in ('planned','unplanned'))" not in incident_sql.replace('  ', ' '):
        fail('required incidents CHECK constraints are missing')
    if con.execute('PRAGMA foreign_key_check').fetchall():
        fail('foreign-key integrity failed')
    if sorted(con.execute('SELECT * FROM incidents').fetchall()) != expected_incidents:
        fail('incident rows do not match authoritative source rows')
    if sorted(con.execute('SELECT * FROM incident_tags').fetchall()) != expected_tags:
        fail('normalized tag rows mismatch')

    summary_cols = [r[1] for r in con.execute('PRAGMA table_info(service_summary)')]
    if summary_cols != ['service','incident_count','unplanned_count','sev12_unplanned_count','unplanned_minutes']:
        fail(f'service_summary columns mismatch: {summary_cols}')
    expected_summary = {}
    for row in expected_incidents:
        service, severity, duration, disposition = row[1], row[2], row[5], row[7]
        x = expected_summary.setdefault(service, [0,0,0,0])
        x[0] += 1
        if disposition == 'unplanned':
            x[1] += 1; x[3] += duration
            if severity in (1,2): x[2] += 1
    summary = sorted((service, *values) for service, values in expected_summary.items())
    if sorted(con.execute('SELECT * FROM service_summary').fetchall()) != summary:
        fail('service_summary values mismatch')

    by_id = {r[0]: r for r in expected_incidents}
    tags_by_id = {iid: [] for iid in by_id}
    for iid, tag in expected_tags: tags_by_id[iid].append(tag)
    report_rows = []
    for iid, row in by_id.items():
        if row[7] == 'unplanned' and row[2] in (1,2):
            report_rows.append((iid,row[1],str(row[2]),row[3],str(row[5]),','.join(tags_by_id[iid])))
    report_rows.sort(key=lambda r: (int(r[2]), r[3], r[0]))
    expected_bytes = ('incident_id\tservice\tseverity\tstarted_at\tduration_min\ttags\n' + ''.join('\t'.join(r)+'\n' for r in report_rows)).encode()
    report = ROOT/'exceptions.tsv'
    if not report.is_file() or report.read_bytes() != expected_bytes:
        fail('exceptions.tsv content, ordering, or byte format mismatch')
    print('all incident audit checks passed')

if __name__ == '__main__':
    try:
        main()
    except Exception as exc:
        print(f'FAIL: {exc}', file=sys.stderr)
        sys.exit(1)
